DENIED = {"viewer": {"write", "delete"}, "editor": {"delete"}, "admin": set()}


def can(role, action):
    return action not in DENIED.get(role, set())

solution:
PERMISSIONS = {
    "viewer": {"read"},
    "editor": {"read", "write"},
    "admin": {"read", "write", "delete"},
}


def can(role, action):
    return action in PERMISSIONS.get(role, set())

